(async()=>{const root=document.getElementById("app-root");const parts=["body-01.html","body-02.html","body-03.html","body-04.html","body-05.html"];let html="";for(const p of parts){html+=await (await fetch(p)).text();}root.outerHTML=html;const scripts=["app-01.js","app-02.js","app-03.js","app-04.js","app-05.js","app-06.js","app-07.js","app-08.js","app-09.js","app-10.js","app-11.js","app-12.js","app-13.js","app-14.js","app-17.js","app-15.js","app-16.js","app-19.js","app-18.js","app-20.js","app-21.js","app-22.js","app-23.js","app-24.js","app-25.js","app-26.js","install.js"];for(const src of scripts){await new Promise((resolve,reject)=>{const s=document.createElement("script");s.src=src;s.onload=resolve;s.onerror=reject;document.body.appendChild(s);});}})().catch(e=>{document.body.innerHTML=`<pre>Falha ao iniciar o Lattes Assist: ${e.message}</pre>`;});